content:
I'll add the spot-capacity node pool to the prod clusters configuration by importing `RegionNodePool` and adding a second pool call.

`src/envs/prod/clusters/main.ts`
```typescript
/**
 * prod environment — clusters build root.
 *
 * `chant build src/envs/prod/clusters` sees this file only. The output lands
 * at `dist/prod/clusters/manifests.yaml`, the path `../delivery/main.ts`'s
 * `myapp-prod-clusters` Kustomization reconciles.
 */

import {
  RegionCluster,
  RegionNodePool,
} from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";

// ── Cluster ──────────────────────────────────────────────────────────────────
// SPEC: 4 nodes, t3.large. Private API endpoint; IRSA/OIDC provider on.

export const cluster = RegionCluster({
  name: "myapp-prod",
  env: ENV,
  region: REGION,
  availabilityZones: ["us-east-1a", "us-east-1b", "us-east-1c"],
  nodeCount: 4,
  instanceType: "t3.large",
  minNodeCount: 4,
  maxNodeCount: 8,
  publicEndpoint: false,
  associateOIDCProvider: true,
});

// ── Spot Node Pool ───────────────────────────────────────────────────────────
// Additional capacity pool for burst batch workloads at lower cost.

export const spotNodePool = RegionNodePool({
  name: "myapp-prod-nodes-spot",
  clusterName: "myapp-prod",
  env: ENV,
  instanceType: "t3.large",
  replicas: 2,
  capacityType: "spot",
  availabilityZones: ["us-east-1a", "us-east-1b", "us-east-1c"],
});
```

Added `RegionNodePool` to the import and created a new `spotNodePool` export that joins the existing `myapp-prod` cluster with 2 spot t3.large instances across the same three AZs. The existing on-demand cluster configuration is unchanged.
